/* global unistdesignAjaxPosts */

class AjaxPosts {
  constructor(buttonNode, params) {
    this.button = buttonNode;
    this.isFetching = false;
    this.allLoaded = false;
    this.params = params;
    this.loadPosts = this.loadPosts.bind(this);
  }

  async loadPosts() {
    if (this.isFetching || this.allLoaded) {
      return;
    }

    const data = new FormData();
    data.append('action', this.params.action);
    data.append('query', this.params.posts);
    data.append('page', this.params.currentPage);
    data.append('nonce', this.params.nonce);
    this.isFetching = true;
    this.button.classList.add('is-fetching');
    const res = await fetch(this.params.url, {
      method: 'POST',
      body: data
    });

    if (res.status === 200) {
      const posts = await res.text();

      if (!posts.length) {
        this.allLoaded = true;
        this.button.disabled = true;
        this.button.innerHTML = 'All posts loaded';
      } else {
        this.ajaxDiv.innerHTML += posts;
        this.params.currentPage++;
      }
    } else {
      this.ajaxDiv.innerHTML += 'Could not fetch posts. Please try again or refresh.';
    }

    this.isFetching = false;
    this.button.classList.remove('is-fetching');
  }

  init() {
    this.button.addEventListener('click', this.loadPosts);
    this.ajaxDiv = document.createElement('div');
    this.ajaxDiv.className = 'posts__ajax';
    this.button.parentNode.insertBefore(this.ajaxDiv, this.button);
  }

}

